// Authored StackYoga adapter test. This file is not generated by Microsoft Kiota.
import assert from "node:assert/strict";
import test from "node:test";
import { buildStorageObjectUrl, storageObjectForLogicalKey } from "../dist/index.js";

test("hierarchical keys preserve separators and encode every segment", () => {
    assert.equal(
        buildStorageObjectUrl("https://apps.example.test/", "avatars/My photo (1).png"),
        "https://apps.example.test/v1/storage/objects/avatars/My%20photo%20%281%29.png",
    );
    assert.equal(
        buildStorageObjectUrl("https://apps.example.test:8443/", "café/猫.json"),
        "https://apps.example.test:8443/v1/storage/objects/caf%C3%A9/%E7%8C%AB.json",
    );
});

test("invalid logical keys fail before a generated builder is used", () => {
    for (const value of [
        "", " ", "/a", "projects/a", "https://example.test/a", "a\\b", "a%b", "a\0b",
        "a//b", ".", "..", "a/./b", "a/../b", "x".repeat(1025),
    ]) {
        assert.throws(() => buildStorageObjectUrl("https://apps.example.test/", value), Error, value);
    }
});

test("the adapter overrides the generated item builder with a raw URL", () => {
    const calls = [];
    const expected = { kind: "generated-with-url-builder" };
    const objects = {
        byKey(value) {
            calls.push(["byKey", value]);
            return {
                withUrl(rawUrl) {
                    calls.push(["withUrl", rawUrl]);
                    return expected;
                },
            };
        },
    };

    const actual = storageObjectForLogicalKey(
        objects,
        "https://apps.example.test/",
        "avatars/user 1/photo.png",
    );

    assert.equal(actual, expected);
    assert.deepEqual(calls, [
        ["byKey", "_stackyoga_raw_url_"],
        ["withUrl", "https://apps.example.test/v1/storage/objects/avatars/user%201/photo.png"],
    ]);
});
